package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original API67 source, metadata and assertions admitted on Salesforce in Wave59.
func TestRunJSONEOFDiscriminatorContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeClosureEOF67.cls"), "@IsTest private class GladeClosureEOF67 {\nprivate static void finish(List<Object> rows,Integer expected,String caseName){System.assertEquals(expected,rows.size(),'All discriminator operations retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Observation exceeds transport bound');System.assertEquals(expectedRows(caseName),rows,'Exact source-bound Salesforce rows and keysets');}\nprivate static void one(List<Object> rows,String input){Map<String,Object> row=new Map<String,Object>{'input'=>input,'utf16Length'=>input.length()};try{Object result=JSON.deserializeUntyped(input);row.put('returned',true);row.put('value',result);}catch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}rows.add(row);}\n@IsTest static void array(){List<Object> rows=new List<Object>();one(rows,'[12');one(rows,'[true');one(rows,'[null');one(rows,'[\"x\"');finish(rows,4,'array');}\n@IsTest static void object(){List<Object> rows=new List<Object>();one(rows,'{\"a\":12');one(rows,'{\"a\":true');one(rows,'{\"a\":null');one(rows,'{\"a\":\"x\"');finish(rows,4,'object');}\n@IsTest static void nestedArray(){List<Object> rows=new List<Object>();one(rows,'{\"a\":[12');one(rows,'{\"a\":[true');one(rows,'{\"a\":[null');one(rows,'{\"a\":[\"x\"');finish(rows,4,'nestedArray');}\n@IsTest static void nestedObject(){List<Object> rows=new List<Object>();one(rows,'[{\"a\":12');one(rows,'[{\"a\":true');one(rows,'[{\"a\":null');one(rows,'[{\"a\":\"x\"');finish(rows,4,'nestedObject');}\n@IsTest static void incompleteEscapes(){List<Object> rows=new List<Object>();one(rows,'[\"x\\\\');one(rows,'{\"a\":\"x\\\\');one(rows,'{\"a\":[\"x\\\\');finish(rows,3,'incompleteEscapes');}\n@IsTest static void incompleteUnicodeEscapes(){List<Object> rows=new List<Object>();one(rows,'[\"\\\\u12');one(rows,'{\"a\":\"\\\\u12');one(rows,'[{\"a\":\"\\\\u12');finish(rows,3,'incompleteUnicodeEscapes');}\nprivate static List<Object> expectedRows(String caseName){\nif(caseName=='array'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:10]','type'=>'System.JSONException','utf16Length'=>3,'input'=>'[12'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:16]','type'=>'System.JSONException','utf16Length'=>5,'input'=>'[true'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:16]','type'=>'System.JSONException','utf16Length'=>5,'input'=>'[null'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:9]','type'=>'System.JSONException','utf16Length'=>4,'input'=>'[\"x\"'}};}\nif(caseName=='object'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:22]','type'=>'System.JSONException','utf16Length'=>7,'input'=>'{\"a\":12'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:28]','type'=>'System.JSONException','utf16Length'=>9,'input'=>'{\"a\":true'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:28]','type'=>'System.JSONException','utf16Length'=>9,'input'=>'{\"a\":null'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:17]','type'=>'System.JSONException','utf16Length'=>8,'input'=>'{\"a\":\"x\"'}};}\nif(caseName=='nestedArray'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:25]','type'=>'System.JSONException','utf16Length'=>8,'input'=>'{\"a\":[12'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:31]','type'=>'System.JSONException','utf16Length'=>10,'input'=>'{\"a\":[true'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:31]','type'=>'System.JSONException','utf16Length'=>10,'input'=>'{\"a\":[null'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for ARRAY (from [line:1, column:19]','type'=>'System.JSONException','utf16Length'=>9,'input'=>'{\"a\":[\"x\"'}};}\nif(caseName=='nestedObject'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:25]','type'=>'System.JSONException','utf16Length'=>8,'input'=>'[{\"a\":12'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:31]','type'=>'System.JSONException','utf16Length'=>10,'input'=>'[{\"a\":true'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:31]','type'=>'System.JSONException','utf16Length'=>10,'input'=>'[{\"a\":null'},new Map<String,Object>{'message'=>'Unexpected end-of-input: expected close marker for OBJECT (from [line:1, column:19]','type'=>'System.JSONException','utf16Length'=>9,'input'=>'[{\"a\":\"x\"'}};}\nif(caseName=='incompleteEscapes'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:9]','type'=>'System.JSONException','utf16Length'=>4,'input'=>'[\"x\\\\'},new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:17]','type'=>'System.JSONException','utf16Length'=>8,'input'=>'{\"a\":\"x\\\\'},new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:19]','type'=>'System.JSONException','utf16Length'=>9,'input'=>'{\"a\":[\"x\\\\'}};}\nif(caseName=='incompleteUnicodeEscapes'){return new List<Object>{new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:13]','type'=>'System.JSONException','utf16Length'=>6,'input'=>'[\"\\\\u12'},new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:21]','type'=>'System.JSONException','utf16Length'=>10,'input'=>'{\"a\":\"\\\\u12'},new Map<String,Object>{'message'=>'Unexpected end-of-input in character escape sequence at [line:1, column:23]','type'=>'System.JSONException','utf16Length'=>11,'input'=>'[{\"a\":\"\\\\u12'}};}\nSystem.assert(false,'Unknown exact case');return null;\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeClosureEOF67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}], \"sourceApiVersion\": \"67.0\"}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 6 || got.Passed != 6 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Exact discriminator contracts: %s", data)
	}
}
